import re

def create_account(
    email: str,
    password_hash: str,
) -> dict:
    BCRYPT_HASH_PATTERN = re.compile(r"^\$2[aby]\$\d{2}\$[./0-9A-Za-z]{53}$")

    if not BCRYPT_HASH_PATTERN.match(password_hash):
        raise ValueError(
            "Invalid password hash format. Expected a strong hash generated by a key-stretching "
            "algorithm (e.g., bcrypt) to ensure credential protection."
        )

    account = {
        "email": email,
        "password_hash": password_hash,
        "role": "member",
        "status": "active",
    }

    return account_repository.save(
        account
    )
